begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000', ('40000000-0000-4000-a000-'||lpad(n::text,12,'0'))::uuid,
'authenticated','authenticated','phase4-'||n||'@pgtap.test','','{}','{"role":"SUPER_ADMIN"}',now(),now() from generate_series(1,5) n;
update public.profiles set role='SUPER_ADMIN' where id in ('40000000-0000-4000-a000-000000000001','40000000-0000-4000-a000-000000000002','40000000-0000-4000-a000-000000000005');
update public.profiles set role='PROJECT_MANAGER' where id='40000000-0000-4000-a000-000000000003';
update public.profiles set is_active=false where id='40000000-0000-4000-a000-000000000005';
select ok(not has_function_privilege('anon','public.admin_update_employee_details(uuid,text,text)','execute'),'anon denied admin_update_employee_details');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000003","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_update_employee_details('40000000-0000-4000-a000-000000000004',' New Name ','https://cdn.test/a.png')$q$,'42501','forbidden','non-admin denied admin_update_employee_details, actor 3');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000004","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_update_employee_details('40000000-0000-4000-a000-000000000004',' New Name ','https://cdn.test/a.png')$q$,'42501','forbidden','non-admin denied admin_update_employee_details, actor 4');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000005","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_update_employee_details('40000000-0000-4000-a000-000000000004',' New Name ','https://cdn.test/a.png')$q$,'42501','forbidden','non-admin denied admin_update_employee_details, actor 5');
