reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000003","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000004',' P4-001 ')$q$,'42501','forbidden','non-admin denied admin_set_employee_code, actor 3');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000004","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000004',' P4-001 ')$q$,'42501','forbidden','non-admin denied admin_set_employee_code, actor 4');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000005","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000004',' P4-001 ')$q$,'42501','forbidden','non-admin denied admin_set_employee_code, actor 5');
select ok(not has_function_privilege('anon','public.admin_set_employee_role(uuid,public.app_role)','execute'),'anon denied admin_set_employee_role');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000003","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_role('40000000-0000-4000-a000-000000000004','PROJECT_MANAGER')$q$,'42501','forbidden','non-admin denied admin_set_employee_role, actor 3');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000004","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_role('40000000-0000-4000-a000-000000000004','PROJECT_MANAGER')$q$,'42501','forbidden','non-admin denied admin_set_employee_role, actor 4');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000005","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_role('40000000-0000-4000-a000-000000000004','PROJECT_MANAGER')$q$,'42501','forbidden','non-admin denied admin_set_employee_role, actor 5');
select ok(not has_function_privilege('anon','public.admin_set_employee_active(uuid,boolean)','execute'),'anon denied admin_set_employee_active');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000003","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_active('40000000-0000-4000-a000-000000000004',false)$q$,'42501','forbidden','non-admin denied admin_set_employee_active, actor 3');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000004","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_active('40000000-0000-4000-a000-000000000004',false)$q$,'42501','forbidden','non-admin denied admin_set_employee_active, actor 4');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000005","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_active('40000000-0000-4000-a000-000000000004',false)$q$,'42501','forbidden','non-admin denied admin_set_employee_active, actor 5');
