reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000003","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_git_organizer('40000000-0000-4000-a000-000000000004',true)$q$,'42501','forbidden','non-admin denied admin_set_git_organizer, actor 3');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000004","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_git_organizer('40000000-0000-4000-a000-000000000004',true)$q$,'42501','forbidden','non-admin denied admin_set_git_organizer, actor 4');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000005","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_git_organizer('40000000-0000-4000-a000-000000000004',true)$q$,'42501','forbidden','non-admin denied admin_set_git_organizer, actor 5');
