select lives_ok($q$select public.admin_update_employee_details('40000000-0000-4000-a000-000000000004',' New Name ','https://cdn.test/a.png')$q$,'admin succeeds admin_update_employee_details');
select lives_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000004',' P4-001 ')$q$,'admin succeeds admin_set_employee_code');
select lives_ok($q$select public.admin_set_employee_role('40000000-0000-4000-a000-000000000004','PROJECT_MANAGER')$q$,'admin succeeds admin_set_employee_role');
select lives_ok($q$select public.admin_set_employee_active('40000000-0000-4000-a000-000000000004',false)$q$,'admin succeeds admin_set_employee_active');
select lives_ok($q$select public.admin_set_git_organizer('40000000-0000-4000-a000-000000000004',true)$q$,'admin succeeds admin_set_git_organizer');
reset role;
select is((select count(*)::int from private.employee_audit_log where actor_id='40000000-0000-4000-a000-000000000001'),5,'each successful change audited');
select is((select old_values from private.employee_audit_log where actor_id='40000000-0000-4000-a000-000000000001' and action='EMPLOYEE_CODE_UPDATED'),'{"employee_code":null}'::jsonb,'audit only relevant fields');
select is((select employee_code from public.profiles where id='40000000-0000-4000-a000-000000000004'),'P4-001','code trimmed');
select is((select full_name from public.profiles where id='40000000-0000-4000-a000-000000000004'),'New Name','name trimmed');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000001","role":"authenticated"}',true); set local role authenticated;
select lives_ok($q$select public.admin_update_employee_details('40000000-0000-4000-a000-000000000004',' New Name ','https://cdn.test/a.png')$q$,'no-op succeeds admin_update_employee_details');
select lives_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000004',' P4-001 ')$q$,'no-op succeeds admin_set_employee_code');
select lives_ok($q$select public.admin_set_employee_role('40000000-0000-4000-a000-000000000004','PROJECT_MANAGER')$q$,'no-op succeeds admin_set_employee_role');
select lives_ok($q$select public.admin_set_employee_active('40000000-0000-4000-a000-000000000004',false)$q$,'no-op succeeds admin_set_employee_active');
select lives_ok($q$select public.admin_set_git_organizer('40000000-0000-4000-a000-000000000004',true)$q$,'no-op succeeds admin_set_git_organizer');
select throws_ok($q$select public.admin_update_employee_details('40000000-0000-4000-a000-000000000004',' ',null)$q$,'22023','invalid_full_name','reject invalid_full_name');
select throws_ok($q$select public.admin_update_employee_details('40000000-0000-4000-a000-000000000004','Name','http://bad.test')$q$,'22023','invalid_avatar_url','reject invalid_avatar_url');
select throws_ok($q$select public.admin_set_employee_role('40000000-0000-4000-a000-000000000004','ROOT')$q$,'22P02','invalid input value for enum app_role: "ROOT"','reject invalid input value for enum app_role: "ROOT"');
select throws_ok($q$select public.admin_set_employee_role('40000000-0000-4000-a000-000000000001','DEVELOPER')$q$,'22023','self_demotion','reject self_demotion');
select throws_ok($q$select public.admin_set_employee_active('40000000-0000-4000-a000-000000000001',false)$q$,'22023','self_deactivation','reject self_deactivation');
select throws_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000003','P4-001')$q$,'23505',null,'duplicate code rejected');
select lives_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000003','p4-001')$q$,'code remains case sensitive');
select lives_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000003','  ')$q$,'blank code clears');
select throws_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000003',repeat('x',33))$q$,'22023','invalid_employee_code','code length validated');
select throws_ok($q$select public.admin_set_employee_role('40000000-0000-4000-a000-000000000003',null)$q$,'22023','invalid_role','null role rejected');
select throws_ok($q$select public.admin_set_employee_active('40000000-0000-4000-a000-000000000003',null)$q$,'22023','invalid_status','null status rejected');
select throws_ok($q$select public.admin_set_git_organizer('40000000-0000-4000-a000-000000000003',null)$q$,'22023','invalid_git_organizer','null permission rejected');
select throws_ok($q$select public.admin_set_employee_code('49999999-0000-4000-a000-000000000000','X')$q$,'P0002','employee_not_found','missing target rejected');
select throws_ok($q$update private.employee_audit_log set action='EMPLOYEE_ACTIVATED'$q$,'42501',null,'audit update denied');
select throws_ok($q$delete from private.employee_audit_log$q$,'42501',null,'audit delete denied');
select throws_ok($q$insert into private.employee_audit_log(actor_id,target_employee_id,action,old_values,new_values) values('40000000-0000-4000-a000-000000000001','40000000-0000-4000-a000-000000000004','EMPLOYEE_ACTIVATED','{}','{}')$q$,'42501',null,'audit spoof insert denied');
select ok(not has_function_privilege('authenticated','private.lock_employee_admin_target(uuid)','execute'),'lock helper inaccessible');
select ok(not has_column_privilege('cyclo_employee_api','public.profiles','email','update'),'owner cannot change email');
select ok(not has_column_privilege('cyclo_employee_api','public.profiles','onboarded_at','update'),'owner cannot bypass onboarding');
reset role;
select is((select count(*)::int from private.employee_audit_log where actor_id='40000000-0000-4000-a000-000000000001'),7,'no-op and failed mutations add no audit');
create function pg_temp.fail_audit() returns trigger language plpgsql as $$begin raise exception 'audit unavailable'; end;$$;
create trigger phase4_fail_audit before insert on private.employee_audit_log for each row execute function pg_temp.fail_audit();
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000001","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000003','ROLLBACK')$q$,'P0001','audit unavailable','audit failure propagates');
reset role;
select is((select employee_code from public.profiles where id='40000000-0000-4000-a000-000000000003'),null::text,'audit failure rolls back mutation');
drop trigger phase4_fail_audit on private.employee_audit_log;
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000002","role":"authenticated"}',true); set local role authenticated;
select lives_ok($q$select public.admin_set_employee_role('40000000-0000-4000-a000-000000000001','DEVELOPER')$q$,'second admin can manage first');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000001","role":"authenticated"}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_git_organizer('40000000-0000-4000-a000-000000000004',false)$q$,'42501','forbidden','demoted caller immediately denied');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000004","role":"authenticated"}',true); set local role authenticated;
select lives_ok($q$update public.profiles set full_name='SPOOF' where id='40000000-0000-4000-a000-000000000003'$q$,'non-admin update to other row affects zero rows');
reset role;
select isnt((select full_name from public.profiles where id='40000000-0000-4000-a000-000000000003'),'SPOOF','RLS prevents modifying another employee');
update public.profiles set role='DEVELOPER' where role='SUPER_ADMIN' and id<>'40000000-0000-4000-a000-000000000002';
select throws_ok($q$update public.profiles set role='DEVELOPER' where id='40000000-0000-4000-a000-000000000002'$q$,'23514',null,'last admin demotion trigger preserved');
select throws_ok($q$update public.profiles set is_active=false where id='40000000-0000-4000-a000-000000000002'$q$,'23514',null,'last admin deactivation trigger preserved');
select is((select active_count from private.super_admin_guard),1::bigint,'counter consistent');
reset role; select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-a000-000000000002","role":"authenticated"}',true); set local role authenticated;
select lives_ok($q$select public.get_employee('40000000-0000-4000-a000-000000000003')$q$,'read RPC still works');
select lives_ok($q$select public.admin_set_employee_active('40000000-0000-4000-a000-000000000004',true)$q$,'reactivate');
select lives_ok($q$select public.admin_set_git_organizer('40000000-0000-4000-a000-000000000004',false)$q$,'revoke organizer');
reset role;
select is((select onboarded_at from public.profiles where id='40000000-0000-4000-a000-000000000004'),null::timestamptz,'reactivation preserves onboarding');
