select lives_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000004',E'\tDevv\n')$q$,'code trims whitespace without trimming letters');
reset role;
select is((select full_name from public.profiles where id='40000000-0000-4000-a000-000000000004'),'Devv','name ending in v preserved');
select is((select employee_code from public.profiles where id='40000000-0000-4000-a000-000000000004'),'Devv','code ending in v preserved');
select set_config('request.jwt.claims','{}',true); set local role authenticated;
select throws_ok($q$select public.admin_set_employee_code('40000000-0000-4000-a000-000000000004','X')$q$,'42501','unauthenticated','authenticated role without identity denied');
reset role;
select throws_ok($q$insert into private.employee_audit_log(actor_id,target_employee_id,action,old_values,new_values) values('40000000-0000-4000-a000-000000000002','40000000-0000-4000-a000-000000000004','ARBITRARY','{}','{}')$q$,'23514',null,'audit action constrained');
select ok(not exists(select 1 from private.employee_audit_log where target_employee_id='40000000-0000-4000-a000-000000000004' and action='EMPLOYEE_PROFILE_UPDATED' and (old_values ? 'avatar_url' or new_values ? 'avatar_url')),'profile audit never stores raw avatar URLs or signed tokens');
select ok(exists(select 1 from private.employee_audit_log where target_employee_id='40000000-0000-4000-a000-000000000004' and action='EMPLOYEE_PROFILE_UPDATED' and new_values->>'avatar_url_sha256' = encode(sha256(convert_to('https://cdn.test/a.png','UTF8')),'hex')),'avatar changes audited by digest');
select * from finish(); rollback;
